function firstBucketMinGreaterThan(d) {
    let lo = 0, hi = buckets.length;
    while (lo < hi) {
        const m = (lo + hi) >> 1;
        const v = buckets[m][0];
        if (v !== undefined && v > d) hi = m; else lo = m + 1;
    }
    return lo;
}

function countLE(d) {
    const idx = firstBucketMinGreaterThan(d); // buckets[idx] tem min > d
    let cnt = 0;
    for (let i = 0; i < idx - 1; i++) cnt += buckets[i].length;
    if (idx - 1 >= 0) cnt += upperBound(buckets[idx - 1], d);
    return cnt;
}

function insert(d) {
    let idx = firstBucketMinGreaterThan(d);
    if (idx >= buckets.length || idx === -1) idx = buckets.length - 1;
    // se nenhum bucket tem min > d, vai pro último (d é >= todos os mins)
    if (firstBucketMinGreaterThan(d) >= buckets.length) idx = buckets.length - 1;
    const b = buckets[idx];
    const pos = upperBound(b, d);
    b.splice(pos, 0, d);
    if (b.length > SPLIT) {
        const mid = b.length >> 1;
        const right = b.splice(mid);
        buckets.splice(idx + 1, 0, right);
    }
}

let out = [];
let idx = 1;
let P = 0;
for (let k = 0; k < n; k++) {
    let x = data[idx++] + P;
    let y = data[idx++] + P;
    const d = x * x + y * y;
    const c = countLE(d); // nº de flechas anteriores com distância <= atual
    out.push(c);
    insert(d);
    P = c;
}

fs.writeSync(1, out.join('\n') + '\n');
